// Generates lib/types/database.ts from the local Supabase database.
//
//   pnpm db:types         regenerate the file
//   pnpm db:types:check   exit 1 if the file doesn't match the database (used in CI)
//
// Needs local Supabase running (`pnpm db:start`) with all migrations applied.

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import * as prettier from 'prettier';

const OUT = 'lib/types/database.ts';

const HEADER = `// ⚠️ GENERATED FILE. DO NOT EDIT BY HAND.
// Generated by \`pnpm db:types\` (scripts/db-types.mjs) from the local Supabase database.
// To change it: add a migration in supabase/migrations/, apply it, then run \`pnpm db:types\`.
// CI fails if this file doesn't match the migrations.

`;

const check = process.argv.includes('--check');

let generated;
try {
  // A fixed command string run through the shell, so the CLI's .cmd shim resolves on
  // Windows too. Targets the local stack by default.
  generated = execSync('supabase gen types typescript --schema public', {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'inherit'],
  });
} catch {
  console.error(
    '\nCould not generate types. Is local Supabase running? Try `pnpm db:start`.'
  );
  process.exit(1);
}

const options = (await prettier.resolveConfig(OUT)) ?? {};
const output = await prettier.format(HEADER + generated.replace(/\r\n/g, '\n'), {
  ...options,
  filepath: OUT,
});

if (!check) {
  writeFileSync(OUT, output);
  console.log(`Wrote ${OUT}`);
  process.exit(0);
}

let current = '';
try {
  current = readFileSync(OUT, 'utf8').replace(/\r\n/g, '\n');
} catch {
  // Missing file counts as out of date.
}

if (current !== output) {
  console.error(
    `${OUT} is out of date with the database schema.\n` +
      'Apply your migrations (`pnpm exec supabase migration up`), run `pnpm db:types`, ' +
      'and commit the result.'
  );
  process.exit(1);
}

console.log(`${OUT} is up to date.`);
